<?php
namespace TerribleMail;
defined('ABSPATH') || exit;
if (!current_user_can('manage_options')) return;
try { $c=Settings::get(); $providers=Transports::all(); } catch (\Throwable $e) { echo '<div class="wrap"><h1>Terrible Mail</h1><p>'.esc_html($e->getMessage()).'</p></div>'; return; }
$selected=sanitize_key($_GET['transport']??$c['transport']);$provider=$providers[$selected]??null;
\TerribleTools\Admin::header('Terrible Mail','Send mail. See what happened.',$c['enabled']?'Delivery enabled':'Delivery disabled');
$notice=get_transient('terrible_mail_notice_'.get_current_user_id());if($notice){delete_transient('terrible_mail_notice_'.get_current_user_id());echo '<div class="tt-success" role="status">'.esc_html($notice).'</div>';}
$error=get_transient('terrible_mail_error_'.get_current_user_id());if($error){delete_transient('terrible_mail_error_'.get_current_user_id());echo '<div class="tt-error" role="alert">'.esc_html($error).'</div>';}
echo '<div class="tt-grid">';\TerribleTools\Admin::card('Delivery connection','CURRENT ROUTE');
echo '<p class="tt-badge">'.esc_html(($providers[$c['transport']]??null)?->label()??'Provider unavailable').'</p><p>Sender: <strong>'.esc_html($c['from']?:'Not configured').'</strong></p><p>'.($c['enabled']?'WordPress mail uses this connection.':'Save your connection settings below and enable delivery to start routing WordPress mail.').'</p><a class="button" href="#tm-settings">Edit connection</a></section>';
\TerribleTools\Admin::card('Send a test','CHECK DELIVERY');self::begin('test');echo '<label for="tm-to">Recipient<input type="email" id="tm-to" name="to" value="'.esc_attr(wp_get_current_user()->user_email).'" required></label>';submit_button('Send test');echo '</form><p class="tt-muted">Acceptance confirms the sending service received your message. Check the recipient’s inbox too.</p></section></div>';
echo '<details class="tt-card" id="tm-settings" '.(!$c['enabled'] || !$provider || isset($_GET['transport'])?'open':'').'><summary>Connection settings</summary><p class="tt-actions">';
foreach($providers as$id=>$p)echo '<a class="button" '.($id===$selected?'aria-current="page"':'').' href="'.esc_url(\TerribleTools\Admin::url('terrible-mail',['transport'=>$id])).'#tm-settings">'.esc_html($p->label()).'</a> ';echo '</p>';
if(!$provider)echo '<p class="tt-error">The selected provider is unavailable. Reinstall its Integrations pack or select a configured transport. Delivery will not silently fall back.</p>';
else{
 self::begin('save');echo '<input type="hidden" name="transport" value="'.esc_attr($selected).'"><label><input type="checkbox" name="enabled" value="1" '.checked($c['enabled'],true,false).'> Use Terrible Mail for WordPress email</label><div class="tt-grid"><div>';
 foreach(['from'=>'Sender email','name'=>'Sender name']as$key=>$label)echo '<label for="tm-'.$key.'">'.$label.'<input id="tm-'.$key.'" name="'.$key.'" type="'.($key==='from'?'email':'text').'" value="'.esc_attr($c[$key]).'" '.($key==='from'?'required':'').'></label>';
 echo '</div><div><h3>'.esc_html($provider->label()).'</h3>';
 foreach($provider->fields()as$key=>[$label,$type,$default]){ $value=$type==='password'?'':($c['providers'][$selected][$key]??$default);echo '<label for="tm-'.esc_attr($key).'">'.esc_html($label);if($selected==='smtp'&&$key==='security'){echo '<select id="tm-security" name="providers[smtp][security]">';foreach(['tls'=>'STARTTLS','ssl'=>'Implicit TLS','none'=>'Unencrypted local relay']as$v=>$l)echo '<option value="'.$v.'" '.selected($value,$v,false).'>'.$l.'</option>';echo '</select>';}else echo '<input id="tm-'.esc_attr($key).'" name="providers['.esc_attr($selected).']['.esc_attr($key).']" type="'.esc_attr($type).'" value="'.esc_attr($value).'" autocomplete="'.($type==='password'?'new-password':'off').'">';echo '</label>';}
 echo '</div></div><p class="tt-muted">Blank secret fields keep saved values. Credentials are encrypted using this installation’s WordPress salts.</p>';submit_button('Save settings');echo '</form>';do_action('terrible_mail_connection_controls',$selected);
}
echo '<hr><h3>Saved connections</h3><p>Keep named configurations for switching delivery services. Save settings above before saving a connection.</p>';self::begin('remember');echo '<label>Connection name<input name="label" required></label>';submit_button('Save current connection','secondary');echo '</form>';
foreach(Settings::connections()as$id=>$saved){echo '<div class="tt-actions"><strong>'.esc_html($saved['label']).'</strong><span>'.esc_html($saved['settings']['transport']).'</span>';foreach(['use'=>'Use connection','forget'=>'Remove']as$op=>$label){self::begin($op);echo '<input type="hidden" name="connection" value="'.esc_attr($id).'">';submit_button($label,'secondary','submit',false);echo '</form>';}echo '</div>';}
echo '</details>';\TerribleTools\Admin::card('Recent submissions','DELIVERY HISTORY');
echo '<p><strong>Accepted</strong>: service received it. <strong>Rejected</strong>: no acceptance; a manual retry may be available. <strong>Unknown</strong>: acceptance could not be confirmed; check the provider before sending again.</p>';
$allRows=History::rows();$historyPage=max(1,min(4,absint($_GET['history_page']??1)));$rows=array_slice($allRows,($historyPage-1)*25,25);if(!$rows)echo '<p class="tt-empty">No submissions yet. Send a test above to check this connection.</p>';else{echo '<div class="tt-table"><table class="widefat striped"><thead><tr><th>Time</th><th>Transport</th><th>Outcome</th><th>Details</th><th>Action</th></tr></thead><tbody>';foreach($rows as$row){echo '<tr><td>'.esc_html(wp_date('M j, H:i',(int)$row['created'])).'</td><td>'.esc_html($row['transport']).'</td><td><strong>'.esc_html(ucfirst($row['status'])).'</strong></td><td>'.esc_html($row['detail']).'</td><td>';if($row['status']==='rejected'&&$row['retryable']&&(int)$row['created']>=time()-DAY_IN_SECONDS){self::begin('retry');echo '<input type="hidden" name="id" value="'.esc_attr($row['id']).'">';submit_button('Retry','secondary','submit',false);echo '</form>';}echo '</td></tr>';}echo '</tbody></table></div>';}
if(count($allRows)>25){echo '<nav class="tt-actions" aria-label="History pages">';for($n=1;$n<=ceil(count($allRows)/25);$n++)echo '<a class="button" href="'.esc_url(\TerribleTools\Admin::url('terrible-mail',['history_page'=>$n])).'">Page '.$n.'</a>';echo '</nav>';}
echo '<details><summary>Retention and privacy</summary><p>Rejected messages are encrypted for manual retry for 24 hours. Accepted and unknown message payloads are discarded. History expires after seven days, with a 500-entry cap; the latest 100 appear here. Bodies and recipients are not displayed.</p>';self::begin('clear');submit_button('Clear history','secondary');echo '</form></details></section></div>';
